      "critique": "# 摄影点评：街边楼房记录\n\n## 一句话总评\n\n这张能记录街边建筑和树木环境，但路灯杆变成了最强视觉中心，真正想拍的建筑被削弱，所以整体更接近普通记录照。\n\n## 评分前检查\n\n- 主体：疑似街边老楼、行道树和路灯所在的街景，但主角不够单一，路灯杆最抢眼。\n- 题材：城市街景 / 建筑环境记录。\n- 图像性质：主要是普通环境记录，有少量街景观察，但视觉意图不够明确。\n- 基础问题等级：基础问题。\n- 硬伤封顶检查：主体存在但偏弱；中央路灯杆和杂乱树枝与建筑竞争；画面偏普通记录；光线普通且叙事弱。可见观看方向正常，不触发旋转/方向封顶。\n- 高分资格：不具备。主体不够明确，背景和前景没有被整理出清晰视觉路径。\n- 故意处理判断：大面积天空、偏灰的逆光和中心路灯不像有效的故意处理；它们没有明显增强情绪或形式感。\n- 故事证据：记录信息。画面说明“这里有楼、树和路”，但缺少明确的情绪、瞬间或视觉想法。\n\n## 五项评分\n\n- 技术：5.5\n- 构图：4.5\n- 光线：5\n- 叙事：4.5\n- 总体：4.8\n\n## 封顶规则\n\n主体存在但较弱，中央路灯杆和杂乱枝干成为显著干扰；同时画面主要是普通记录照，叙事和总体分被限制在 5 分段内。无方向/旋转相关封顶。\n\n## 做得好的地方\n\n- 画面清楚可读，建筑、树、道路关系能看明白。\n- 横向取景适合表现一排建筑和街道环境。\n- 下方绿篱和建筑形成了基本的横向层次。\n\n## 优先修改项\n\n### 1. 问题：路灯杆抢走主体\n\n- 为什么：路灯在画面正中央，又从地面一直伸到天空，视觉重量比建筑还强，观众会先看杆子而不是楼。\n- 下次怎么拍：向左或向右移动几步，让路灯离开正中，或者直接把路灯当主体拍出更明确的极简构图。\n- 这张怎么修：尝试裁掉一部分右侧和上方天空，让建筑占比更高；如果后期工具允许，可以弱化路灯亮度和对比，但不要过度修到不自然。\n\n### 2. 问题：天空占比偏大，信息价值低\n\n- 为什么：上半部大面积浅色天空没有云层、色彩或形状变化，会稀释主体。\n- 下次怎么拍：镜头略向下，保留少量天空即可，把窗户、树干、街道关系放大。\n- 这张怎么修：从上方裁掉约 20%-30% 的空天空，同时保留下方绿篱和建筑横向层次。\n\n### 3. 问题：建筑被树枝遮得太碎\n\n- 为什么：枝条本身有纹理，但它们没有形成图案，也没有把视线引向某个建筑细节。\n- 下次怎么拍：找一个更干净的空隙，专门拍一段窗户、门口或楼体转角；或者靠近树，把树枝作为明确前景框架。\n- 这张怎么修：提高建筑局部对比和清晰度，轻微降低天空高光，让楼体从灰雾里出来一点。\n\n## 建议设置\n\n看不出实际拍摄参数，以下是估计建议：白天街景可以用 ISO 100-400、f/5.6-f/8、快门 1/250 秒以上；手机拍摄时点按建筑主体测光，必要时把曝光补偿拉低一点，避免天空过亮。\n\n## 后期步骤\n\n1. 先裁掉过多天空，保留建筑、树和绿篱的横向关系。\n2. 降低高光，稍微增加去雾或对比，让楼体更清楚。\n3. 轻微提升阴影，但不要把树干提得太灰。\n4. 用局部调整降低路灯杆的存在感，突出建筑窗户区域。\n\n## 下一次练习任务\n\n同一条街再拍 3 张：一张只拍建筑立面，一张用树枝做前景框架，一张把路灯明确当主体。每张拍完都问自己：“观众第一眼应该看哪里？”\n\n归档路径：`/Users/bytedance/Documents/摄影学习/data/archive/20260609-152540-7836367a`\n"
