      "critique": "# 摄影点评：水面野鸭与花枝\n\n## 一句话总评\n\n这张有“春天枝条 + 水面鸭子”的季节感，画面比普通记录照更有想法，但鸭子贴近左边缘，上方枝条又比较抢，整体稳定性还差一点。\n\n## 评分前检查\n\n- 主体：左下区域正在游动的野鸭。\n- 题材：水鸟/环境小景。\n- 图像性质：有季节环境和留白意识，不是单纯物品记录。\n- 基础问题等级：基础问题。\n- 观看方向：画面可正常观看，没有方向或旋转问题阻碍理解。\n- 硬伤封顶检查：主体清楚，但位置太靠左，边缘压力明显；上方花枝和下方枝条都在抢注意力，视觉重心不够稳。\n- 高分资格：不满足 7.5 以上。画面有诗意，但主体、枝条和留白之间的关系还没有组织到足够精确。\n- 故意处理判断：大面积水面留白有一定意图，水纹也能强化环境；但主体贴边和枝条切入过多不是有效的故意构图。\n- 叙事证据：场景/情绪。\n\n## 五项评分\n\n| 项目 | 分数 |\n| --- | --- |\n| 技术 | 6.5 |\n| 构图 | 5.5 |\n| 光线 | 5.5 |\n| 叙事 | 6 |\n| 总体 | 6 |\n\n## 封顶规则\n\n封顶规则：主体贴近左边缘，上方和下方枝条形成明显边缘干扰，构图封顶 5.5，总体封顶 6.0。没有方向/旋转相关封顶。\n\n## 做得好的地方\n\n- 鸭子和花枝放在同一画面里，有季节感和环境关系。\n- 水面颜色干净，整体没有严重曝光或清晰度问题。\n- 鸭子游动方向朝右，理论上能和右侧留白形成空间关系。\n\n## 优先修改项\n\n### 1. 鸭子太贴左边\n\n- 问题：主体离左边缘过近，前方虽然有空间，但身体已经被压到画面边上。\n- 为什么：动物运动方向前方需要留空间，身体后方也要留一点呼吸感，否则像来不及构图。\n- 下次怎么拍：提前预判鸭子的移动方向，等它游到左三分线附近再拍，让前方留白更自然。\n- 这张怎么修：裁掉上方一部分枝条和右侧少量空水面，尽量让鸭子不显得过分靠边；但这张无法完全修复主体贴边问题。\n\n### 2. 花枝抢了主体\n\n- 问题：上方花枝线条多且横跨画面，视觉重量接近甚至超过鸭子。\n- 为什么：观众会先看花枝，再找鸭子，主体顺序被打乱。\n- 下次怎么拍：降低机位或向旁边移动，让花枝只作为少量框景，不要铺满上边缘。\n- 这张怎么修：压低花枝的清晰度和对比，裁掉最上方杂乱枝条，让花枝成为气氛而不是第二主体。\n\n### 3. 光线偏平\n\n- 问题：光线柔和但方向性弱，鸭子体积感不强。\n- 为什么：水鸟照片如果没有好光，主体容易只是“清楚”，但不够立体。\n- 下次怎么拍：优先早晚斜光，等鸭子侧面有亮边或倒影时拍。\n- 这张怎么修：给鸭子局部加一点亮度、纹理和对比；水面降低饱和度一点，让暖色鸭身更突出。\n\n## 建议设置\n\n看不出真实拍摄参数，以下是估计：水鸟游动不算特别快，可用 1/500s 到 1/1000s；连续对焦；连拍；如果有长焦，优先用长焦压缩背景；拍这种“动物 + 枝条”的画面时可以先锁定构图，等主体游进预定位置。\n\n## 后期步骤\n\n1. 裁掉上方约 15%-25% 的杂乱枝条。\n2. 鸭子局部提亮，增加少量纹理和锐度。\n3. 降低花枝对比度，保留粉色点缀即可。\n4. 清理下方边缘几根最分散的枝条。\n5. 轻微加强水面蓝绿色的统一感，但不要调得过艳。\n\n## 下一次练习任务\n\n拍 20 张“动物经过框景”的照片。先选好枝条或倒影做框，再等动物进入干净位置；不要追着动物乱拍，练习让主体进入你已经组织好的画面。\n\n归档路径：/Users/bytedance/Documents/摄影学习/data/archive/20260609-112609-6022b98d\n"
