      "critique": "# 摄影点评：韩国旅游展陈装置\n\n## 一句话总评\n\n这张的色彩和展陈氛围很鲜明，吉祥物也足够醒目，但右侧易拉宝、顶部截断和画面信息过多，让主体表达被明显稀释。\n\n## 评分前检查\n\n- 主体：前景棕色吉祥物与韩国旅游展陈空间。\n- 题材：室内展陈/旅行活动记录，有一定视觉意图。\n- 基础问题等级：基础问题。\n- 硬伤封顶检查：主体清楚；曝光和清晰度基本可用；画面显示方向不阻碍正常观看；右侧易拉宝、顶部胶片灯箱截断、左侧屏幕和大字母一起竞争主体。\n- 高分资格：不具备。色彩和光线有强度，但边缘、背景和主体层级没有控制到高分标准。\n- 故意处理判断：广角收纳大量展陈信息是可以理解的记录选择，但当前元素太多，尚未形成有效的空间叙事。\n- 叙事证据：场景/情绪。\n\n## 五项评分\n\n- 技术：6.7\n- 构图：5.4\n- 光线：6.4\n- 叙事：5.8\n- 总体：5.8\n\n## 封顶规则\n\n右侧易拉宝、顶部截断和多处高亮展陈元素与吉祥物竞争，属于主导性干扰和边缘裁切问题，构图封顶 5.5、总体封顶 6。\n\n## 做得好的地方\n\n- 色彩有吸引力，橙黄灯光和蓝白飞机让展区气氛很明确。\n- 吉祥物位置靠前，第一眼能知道主要拍摄对象。\n- 画面能交代“韩国旅游展陈”的场景，不是孤立拍一个摆件。\n\n## 优先修改项\n\n### 1. 问题：右侧易拉宝太抢\n\n- 为什么：它又亮又大，文字密集，视觉重量接近甚至超过吉祥物。\n- 下次怎么拍：向左或向前移动，避开易拉宝；如果必须保留，就让它作为背景小元素，不要占画面三分之一。\n- 这张怎么修：裁掉右侧大部分易拉宝，保留吉祥物和橙色大字母，画面会更集中。\n\n### 2. 问题：顶部和左侧边缘太满\n\n- 为什么：顶部胶片灯箱被切断，左侧圆屏也只保留一部分，会让画面显得没有收拾好。\n- 下次怎么拍：先决定要不要顶部灯箱。要就给完整弧线，不要就避开它。\n- 这张怎么修：上方裁掉被截断的胶片灯箱，左侧也略裁，让画面主要围绕吉祥物和背景字母。\n\n### 3. 问题：主体层级不够强\n\n- 为什么：吉祥物、字母、屏幕、易拉宝、墙面文字都很亮，观众视线会来回跳。\n- 下次怎么拍：靠近吉祥物，用它遮挡部分杂乱背景，或用竖构图只拍吉祥物和一块干净背景。\n- 这张怎么修：局部提亮吉祥物脸部和帽子，压暗易拉宝和顶部屏幕，建立主次。\n\n## 建议设置\n\n看不出真实拍摄参数，以下是估计建议：室内展陈可以用手机 1x 或 2x，尽量不用超广角，避免把太多边缘杂物拉进来；点按吉祥物脸部测光，曝光略降一点保护灯箱高光。如果用相机，f/4-f/5.6 足够，快门保持安全，ISO 可适度提高。\n\n## 后期步骤\n\n1. 裁掉右侧易拉宝大部分和顶部截断灯箱。\n2. 降低橙黄高光，避免背景灯比主体更抢眼。\n3. 局部提亮吉祥物脸部，增加一点对比度。\n4. 轻微校正垂直线，让展陈空间更稳定。\n\n## 下一次练习任务\n\n在展览或商场装置前拍 5 张“只保留一个主角”的照片。每张拍前先检查四条边：有没有被切开的灯牌、屏幕、路人、展架。只要有，就移动一步再拍。\n\n归档路径：/Users/bytedance/Documents/摄影学习/data/archive/20260609-104934-c6286df4\n"
