      "critique": "# 摄影点评：俯拍院子里的猫\n\n## 一句话总评\n\n这张能记录猫在院子里的位置和动作，但机位太高、猫头靠边、边缘杂物明显，作为动物照片的吸引力还没有建立起来。\n\n## 评分前检查\n\n- 主体：院子里的猫。\n- 题材：宠物 / 生活记录，主要是普通记录照，视觉意图较弱。\n- 基础问题等级：基础问题。\n- 硬伤封顶检查：主体可辨，没有严重虚焦或严重手抖；观看方向正常，不触发旋转封顶；但主体眼神缺失、头部靠近边缘，鞋、碗、地砖和杂草分散注意力，触发主体偏弱、边缘干扰和普通记录照封顶。\n- 高分资格：不具备。动物摄影最关键的眼神、姿态和背景控制都不够。\n- 故意处理判断：俯拍不像有意做图案化或秩序表达，更像随手记录；杂物和高机位不是有效风格。\n\n## 五项评分\n\n- 技术：5/10\n- 构图：4.4/10\n- 光线：5/10\n- 叙事：4.8/10\n- 总体：4.8/10\n\n## 封顶规则\n\n主体偏弱、边缘干扰和普通记录照封顶生效：猫能看清，但眼神和动作没有被抓住，构图最高 5、叙事最高 5、总体最高 5。\n\n## 做得好的地方\n\n- 猫的身体轮廓清楚，尾巴竖起有一点生活瞬间。\n- 画面保留了院子环境，能看出猫在户外活动。\n- 曝光基本可用，白色毛发没有完全糊成一片。\n\n## 优先修改项\n\n### 1. 机位太高\n\n- 问题：从上往下拍，猫被压成地面上的一个形状。\n- 为什么：宠物照片通常靠眼睛、表情和身体姿态打动人，俯拍会削弱亲近感。\n- 下次怎么拍：蹲下，手机降低到猫头附近；如果猫会走动，用连拍等它回头。\n- 这张怎么修：裁掉上方大面积空地，让猫占比更大，但俯拍角度无法彻底补救。\n\n### 2. 猫的位置太靠边\n\n- 问题：猫头贴近右侧边缘，前方没有呼吸空间。\n- 为什么：动物面向或移动的方向需要留白，否则画面显得被截住。\n- 下次怎么拍：把猫放在画面左下或中间偏左，让它前进方向留出空间。\n- 这张怎么修：裁成更紧的竖幅，减少上方空地和底部杂物。\n\n### 3. 边缘杂物抢注意力\n\n- 问题：左下角碗、底部鞋子、地砖和落叶都很显眼。\n- 为什么：生活环境可以保留，但边缘杂物会把视线从猫身上拉走。\n- 下次怎么拍：拍前先扫一眼四个边角，移动半步避开鞋和碗。\n- 这张怎么修：裁掉底部鞋子和左下角碗，局部降低地面清晰度。\n\n## 建议设置\n\n看不出真实 EXIF，以下是估计：\n\n- ISO：户外 100-400。\n- 快门：猫在动时 1/500s 以上；慢走或停住时至少 1/250s。\n- 焦段：手机可用 2x，离猫稍远一点，减少俯拍变形。\n- 对焦：点按猫眼睛或头部，不要只对到地面。\n\n## 后期步骤\n\n1. 裁掉底部鞋子、左下角碗和上方大面积空地。\n2. 局部提亮猫头部，压低白毛高光。\n3. 降低地面杂草、落叶和砖面的清晰度。\n4. 轻微增加猫身对比，让主体从背景里跳出来。\n5. 保持颜色自然，不要把草地调得过绿。\n\n## 下一次练习任务\n\n拍猫时只练“眼睛高度”：蹲低连续拍 10 张，至少等到一张猫回头或眼睛可见。选图时优先看眼神，其次才看背景。\n\n## 归档路径\n\n`/Users/bytedance/Documents/摄影学习/data/archive/20260604-215130-overhead-cat-yard/`\n"
