      "critique": "# 摄影点评：湖面与雪山蓝天\n\n## 一句话总评\n\n这张湖山风景干净、清楚、舒服，但更像一张质量不错的旅行风景记录，主要问题是主体落点不够强，天空和湖面占比大而缺少明确引导。\n\n## 评分前检查\n\n- 主体：远处雪山和湖面风景，左侧山坡作为前景边界。\n- 题材：旅行风景 / 湖山景观，有拍风景的视觉意图，但主视觉落点偏弱。\n- 基础问题等级：基础问题。不是技术失败，而是主体和视觉路径不够集中。\n- 硬伤封顶检查：没有严重虚焦、手抖、严重曝光失败或旋转问题；主体没有不可读，但“远山+湖面+天空”比较平均，构图强度受限。未触发硬伤封顶。\n- 高分资格：不具备。画面清楚、光色舒服，但构图、故事和视觉落点没有达到两个明显强项。\n- 故意处理判断：大天空和大湖面可以作为开阔感处理，但这里缺少小主体、云形、光线或倒影作为落点，所以更像取景偏松。\n- 叙事证据：场景/情绪。能传达开阔湖山和晴天旅行感，但没有更强的关系、瞬间或视觉想法。\n\n## 五项评分\n\n- 技术：6.8/10\n- 构图：6.1/10\n- 光线：6.4/10\n- 叙事：6/10\n- 总体：6.2/10\n\n## 封顶规则\n\n无\n\n## 做得好的地方\n\n- 曝光和清晰度稳定，湖面、山体和天空都能看清。\n- 蓝天、白云、雪山和湖面形成了舒服的旅行风景色彩。\n- 左侧山坡给画面一点空间层次，不是完全平铺。\n\n## 优先修改项\n\n### 1. 主体落点不够强\n\n- 问题：观众能看出是湖山风景，但第一眼不知道该重点看哪座山、哪片云或哪条湖岸线。\n- 为什么：风景照也需要一个视觉终点，否则画面会停留在“这里很好看”的记录层面。\n- 下次怎么拍：选择最高的雪山、最亮的云、船、人或湖岸线作为明确主体，让其他元素服务它。\n- 这张怎么修：裁掉一部分上方天空和下方湖面，把远山放到更重要的位置。\n\n### 2. 天空和湖面比例偏松\n\n- 问题：天空和水面都占大面积，但内部变化不够强。\n- 为什么：大面积留白要靠云形、光线、倒影或小主体支撑，否则会显得空。\n- 下次怎么拍：如果天空普通，就少拍天空；如果湖面普通，就找船、岸线、浪纹或倒影做前景。\n- 这张怎么修：尝试 16:9 或更窄的横幅裁切，减少空天空和重复水纹。\n\n### 3. 光线舒服但不够有方向\n\n- 问题：晴天光线清楚，但没有特别明显的侧光、逆光或云影。\n- 为什么：没有方向性的光会让山体立体感弱一些。\n- 下次怎么拍：清晨、傍晚或云影扫过山体时再拍一张，山的层次会更强。\n- 这张怎么修：给山体增加一点局部对比和去雾，水面降低少量亮度。\n\n## 建议设置\n\n看不出真实 EXIF，以下是估计：\n\n- ISO：100。\n- 光圈：f/8 左右，适合湖山风景。\n- 快门：1/250s 以上，手持拍湖面足够稳。\n- 对焦：对远山或画面中远处三分之一位置；开启网格检查地平线和山线位置。\n\n## 后期步骤\n\n1. 先裁切，减少上方天空和下方重复湖面。\n2. 降低天空高光，保留云的层次。\n3. 远山加少量对比、纹理和去雾。\n4. 湖面降低一点亮度，让雪山更突出。\n5. 控制整体蓝色饱和度，避免天空和湖面过蓝。\n\n## 下一次练习任务\n\n拍湖山风景时先问自己“这张照片的主角是哪一个点”。下一次同一类场景拍三张：以雪山为主、以湖面纹理为主、以天空云形为主，比较哪张最有明确落点。\n\n## 归档路径\n\n`/Users/bytedance/Documents/摄影学习/data/archive/20260604-210553-lake-mountain-sky/`\n"
