      "critique": "# 摄影点评：湖边背影人像\n\n## 一句话总评\n\n这是一张完成度不错的旅行背影人像，人物和湖山环境关系清楚，但人物姿态偏弱、白衣高光和右侧红色浮标让画面还没有到更强的情绪表达。\n\n## 评分前检查\n\n- 主体：湖边穿白色外套的背影人物，环境是湖面、远山和岸边山体。\n- 题材：旅行人像 / 环境人像，不是普通证据记录，有明确视觉意图。\n- 基础问题等级：无。主体清楚，画面方向正常，正常观看不受旋转问题影响。\n- 硬伤封顶检查：没有严重虚焦、明显手抖、主体不可读、严重过曝或严重欠曝；右侧红色浮标和白衣高光是干扰与控制问题，但没有达到硬伤封顶。\n- 高分资格：主体明确，技术和环境分离较好，有进入 7 分段的条件；但人物动作和情绪信息偏少，背景兴趣点也没有和人物形成更强关系，所以不到 7.5。\n- 故意处理判断：背影、浅景深和人物居中偏右是有意的人像处理；白衣偏亮和红色浮标更像现场控制不足，不是有效的表达重点。\n- 叙事证据：场景/情绪。能看出“人在湖边看风景/旅行中”的氛围，但缺少表情、动作或人物关系。\n\n## 五项评分\n\n- 技术：7/10\n- 构图：7/10\n- 光线：6.7/10\n- 叙事：6.8/10\n- 总体：7/10\n\n## 封顶规则\n\n无\n\n## 做得好的地方\n\n- 人物白衣和蓝色湖面分离明显，主体一眼能看到。\n- 背景虚化让山水环境保留氛围，同时没有抢过人物。\n- 横构图给了湖面和远山空间，旅行感成立。\n\n## 优先修改项\n\n### 1. 姿态表达偏弱\n\n- 问题：人物低头背对镜头，动作信息少。\n- 为什么：背影人像不靠表情时，更需要头部方向、肩膀姿态、手部动作来传达情绪。\n- 下次怎么拍：让人物抬头看远山、侧身看湖，或边走边回头抓拍，连续拍 5-10 张选姿态最自然的一张。\n- 这张怎么修：轻微裁掉下方和右侧，让视线更集中到人物头肩与远山之间。\n\n### 2. 白色外套高光偏抢眼\n\n- 问题：白衣面积大，局部亮度偏高，衣服细节变薄。\n- 为什么：白色主体在阳光下会比脸、山和湖更抢注意力。\n- 下次怎么拍：遇到白衣和强光，先减 0.3-0.7 档曝光，优先保住白色细节。\n- 这张怎么修：降低高光和白色色阶，单独压一点外套亮度，保留褶皱。\n\n### 3. 右侧红色浮标分散注意力\n\n- 问题：红点在大面积蓝色湖面里很醒目，但和人物故事关系不强。\n- 为什么：小而高饱和的颜色会把视线从人物背影上拉走。\n- 下次怎么拍：拍前扫一遍画面边缘，向左或向右挪半步避开浮标；如果保留，就让人物视线或动作和它产生关系。\n- 这张怎么修：裁掉右侧一部分，或降低浮标的红色饱和度和亮度。\n\n## 建议设置\n\n看不出真实 EXIF，以下是估计：\n\n- ISO：100-200。\n- 快门：1/250s 以上，保证人物和湖面不糊。\n- 光圈：相机可用 f/2.8-f/4 做环境人像分离；手机可用 2x 或人像模式。\n- 对焦：对人物头部或上半身；白衣强光时曝光补偿 -0.3EV 起步。\n\n## 后期步骤\n\n1. 校正整体色温，让湖水保持自然蓝色，不要过冷。\n2. 降低高光和白色色阶，恢复外套细节。\n3. 人物头发、肩部和背包轻微加清晰度。\n4. 背景蓝色饱和度略降，避免湖面过抢。\n5. 裁切或弱化右侧红色浮标，让主体更稳定。\n\n## 下一次练习任务\n\n同一湖边位置拍三种背影人像：低头、看远方、回头。每种拍 5 张，回看时只比较“哪一张姿态最有情绪”，不要先看清晰度。\n\n## 归档路径\n\n`/Users/bytedance/Documents/摄影学习/data/archive/20260604-210028-lake-back-portrait/`\n"
