      "critique": "# 摄影点评：下午茶展示静物\n\n## 一句话总评\n\n这张照片能清楚记录一组下午茶器具，也有一点精致感，但主体落点太分散，背景文字和菜单把视线拉走，整体更像展示记录而不是一张完成度高的静物照片。\n\n## 评分前检查\n\n- 主体：托盘上的奶茶、杯碟、奶壶和菜单组成的下午茶展示。\n- 题材：室内静物 / 产品展示记录。\n- 图像性质：有摆放和拍摄意图，但主要仍是记录展示内容，视觉故事较弱。\n- 基础问题等级：基础问题。\n- 硬伤封顶检查：主体可读；没有严重虚焦、明显手抖、严重过曝或严重欠曝；画面方向按正常观看方向判断，不构成旋转问题；背景玻璃文字、菜单牌和多件器具共同分散主体，触发“主导干扰 / 视觉落点不清”的构图与总体封顶。\n- 高分资格：不具备。原因是主体不够单一，背景和边缘没有控制好，画面缺少明确的第一观看落点。\n- 故意处理判断：斜向托盘和摆拍感是有意的；高反光、背景文字抢眼、物件过多不像有效的故意处理。\n\n## 五项评分\n\n- 技术：6\n- 构图：5.3\n- 光线：5.5\n- 叙事：5.2\n- 总体：5.5\n\n## 封顶规则\n\n主导干扰、视觉落点不清导致构图分和总体分封顶；无方向/旋转相关封顶。\n\n## 做得好的地方\n\n- 白色杯碟、透明玻璃和深色茶汤形成了材质对比。\n- 托盘的斜线让画面比普通正面记录更有空间感。\n- 曝光基本可用，主体内容都能看清。\n\n## 优先修改项\n\n### 1. 主体太多，第一眼不知道看哪里\n\n- 问题：杯子、奶壶、茶壶、菜单、烛台、背景文字都在争抢注意力。\n- 为什么：静物照片需要一个明确主角；现在每个元素都可读，但没有一个元素被真正突出。\n- 下次怎么拍：先选一个主角，比如前方杯子或中间茶壶，只保留 2-3 个辅助元素；靠近一点，降低机位，让主角占画面更大。\n- 这张怎么修：裁掉上方大块菜单和烛台的一部分，保留托盘、前景杯子和中间茶壶，让视线集中在桌面器具上。\n\n### 2. 背景文字干扰很强\n\n- 问题：玻璃上的大字比主体更醒目，菜单牌也把视线拉到画面上方。\n- 为什么：背景中文字天然会抢眼，观众会先去读字，而不是看杯具和氛围。\n- 下次怎么拍：移动半步，避开玻璃大字；或者用更低角度，让桌面器具挡住背景文字。\n- 这张怎么修：适当压暗背景、降低清晰度和对比度；如果软件支持，可对背景文字做局部弱化。\n\n### 3. 光线有反光，但没有塑造重点\n\n- 问题：白色瓷器和玻璃器皿上有明显亮斑，光线让材质可见，但没有把主角从背景中分离出来。\n- 为什么：静物需要靠光线层次突出主体，否则会停留在“拍清楚了”的记录层面。\n- 下次怎么拍：找侧光位置，让杯子或茶壶一侧亮、一侧暗；避开正面强反光，必要时让手机或相机稍微偏离反射角。\n- 这张怎么修：降低高光，略提阴影；给主体做轻微局部提亮，背景做轻微压暗。\n\n## 建议设置\n\n看不出具体设备和参数，以下是估计建议：\n\n- 手机拍摄：用 1x 或 2x，尽量避免超广角。\n- 曝光：对准白色杯子点按测光后，略微降低曝光 0.3-0.7 档，保住瓷器高光。\n- 对焦：点在最想突出的杯子、茶壶或茶汤边缘。\n- 拍摄方式：竖幅拍静物时，主角占画面高度至少三分之一；拍完检查背景文字是否抢眼。\n\n## 后期步骤\n\n1. 先裁切，减少上方菜单和背景文字占比。\n2. 拉直画面中主要桌面边线，保持托盘斜线但不要让画面显得歪。\n3. 降低高光，恢复白色杯碟细节。\n4. 略微增加主体局部清晰度和对比度。\n5. 背景降低亮度、对比度和饱和度，让它退后。\n\n## 下一次练习任务\n\n拍一组“一个杯子 + 一个茶壶 + 一个辅助物”的静物练习。每次只改变一个条件：机位高度、距离、背景。拍 9 张后选出主体最清楚、背景最干净的一张。\n\n归档路径：/Users/bytedance/Documents/摄影学习/data/archive/20260604-135215-0365a6d2\n"
