      "critique": "# 摄影点评：树冠下的园林桥\n\n## 一句话总评\n\n这张有清楚的树冠框景、桥和倒影，已经不是普通记录照，但桥体偏暗、天空高光和桥前横杆让画面的精致度停在 7 分左右。\n\n## 评分前检查\n\n- 主体：画面下半部的园林小桥，以及它和水面倒影形成的中心景观。\n- 题材：园林/风景小景；有明确视觉意图，不是单纯地点记录。\n- 基础问题等级：无。主体、空间层次和观看路径都成立。\n- 硬伤封顶检查：主体可读；没有严重虚焦或抖动；没有明显旋转错误；高光有溢出但未毁掉主体细节；桥前横杆和亮天空是干扰，但尚未强到触发硬伤封顶。\n- 高分资格：主体清楚，框景和倒影是明确优点；但桥体偏暗、上方亮天空面积较大、桥前横杆切过视觉落点，所以不进入 7.5 或 8。\n- 故意处理判断：树冠遮挡、桥体偏小、上下留白更像是有意用环境包围主体；高光溢出和横杆干扰不像有意表达。\n- 叙事证据：场景/情绪。画面能传达林荫、水面、园林桥的幽静感，但没有更强的瞬间或关系。\n\n## 五项评分\n\n| 项目 | 分数 |\n| --- | --- |\n| 技术 | 6.8 |\n| 构图 | 7.2 |\n| 光线 | 6.6 |\n| 叙事 | 6.8 |\n| 总体 | 7.0 |\n\n## 封顶规则\n\n无。\n\n## 做得好的地方\n\n- 你找到了天然框景：左右树干和上方树冠把视线压向桥，画面有入口感。\n- 桥和倒影形成了稳定的中心落点，比单拍树叶或水面更有主题。\n- 竖幅选择合理，保留了树冠的高度和水面的倒影，让环境感比较完整。\n\n## 优先修改项\n\n1. 问题：桥体和倒影偏暗，主体的存在感不够强。\n   为什么：观众第一眼会先被上方亮叶子和天空吸走，之后才看到桥。\n   下次怎么拍：等光线更柔的时候拍，比如阴天、清晨或傍晚；也可以降低一点机位，让桥和倒影占画面更大比例。\n   这张怎么修：局部提亮桥体和桥洞 0.3-0.6 档，同时压低天空高光，避免整张一起加亮。\n\n2. 问题：桥前的横向杆线切过画面中心。\n   为什么：它正好横穿桥和桥洞附近，会打断视线落点。\n   下次怎么拍：左右移动半步到一步，或稍微升高/降低机位，让横杆避开桥洞和栏杆主体。\n   这张怎么修：如果只做基础修图，可以保留；如果练习精修，可用修复工具淡化最亮的横杆反光。\n\n3. 问题：上半部树冠和天空信息稍多。\n   为什么：树冠框景有效，但顶部亮斑太多会削弱桥的主角位置。\n   下次怎么拍：先确认“桥是主角”，再决定树冠只保留多少；可向前走一点或稍微变焦压缩画面。\n   这张怎么修：裁掉顶部约 8%-12%，同时保留右上树干作为框架。\n\n## 建议设置\n\n看不出实际相机参数，以下是估计：风景小景可用 ISO 100-400、等效 24-35mm、f/5.6-f/8、快门不低于 1/125 秒。遇到这种亮天空加暗桥的场景，建议点按桥体附近测光后略微欠曝 0.3 档，后期再拉回阴影。\n\n## 后期步骤\n\n1. 先校正白平衡，让绿色不要过黄。\n2. 高光降低，重点压天空亮斑；阴影轻微提高，只提桥和水面暗部。\n3. 给桥体和倒影加一点局部清晰度/纹理，树叶区域不要过度锐化。\n4. 轻微暗角或径向滤镜压住四周，把视线收回桥洞。\n5. 最后裁掉少量顶部亮区，保持竖幅和中心桥洞。\n\n## 下一次练习任务\n\n同一座桥拍 3 张：一张低机位强化倒影，一张横幅减少天空，一张只保留桥洞和水面。拍完比较哪一张“桥”最先被看见。\n"
