      "critique": "# 摄影点评：树荫下的水面\n\n## 一句话总评\n\n这张记录到了水面和树荫的环境，但主体不够明确，观众不知道应该看水、树枝、石头还是右侧阴影，所以总体更接近普通风景记录。\n\n## 评分前检查\n\n- 主体：可能是树荫下的水面和岸边植物，但没有一个明确落点。\n- 题材：园林/自然小景；主要是场景记录，有一点光影观察。\n- 基础问题等级：基础问题。画面可读，但主体弱，信息偏散。\n- 硬伤封顶检查：没有严重虚焦或抖动；没有明显旋转错误；局部高光和暗部反差较大但没有毁掉全图；主体存在但不清楚，触发“主体存在但弱”的封顶；同时树枝、石头、水面、右侧暗部互相竞争。\n- 高分资格：不具备。没有清晰主体和明确视觉落点，构图与故事不能进入高分段。\n- 故意处理判断：斑驳光和树叶遮挡可能是想表现林荫感；但小主体/无落点不够有效，不能当作成功的负空间或抽象构图。\n- 叙事证据：记录信息。能说明这里有水、树、石岸，但情绪和视觉想法还不够集中。\n\n## 五项评分\n\n| 项目 | 分数 |\n| --- | --- |\n| 技术 | 6.0 |\n| 构图 | 5.0 |\n| 光线 | 5.5 |\n| 叙事 | 5.0 |\n| 总体 | 5.0 |\n\n## 封顶规则\n\n主体存在但不清楚或偏弱：构图、叙事和总体都被限制在 5 左右；这张没有足够强的光线或瞬间来明显逃逸这个基础问题。\n\n## 做得好的地方\n\n- 你注意到了水面反光和树荫斑驳，这是可以继续练的观察方向。\n- 画面没有严重技术失败，水面、植物和石岸都能辨认。\n- 横幅适合表现空间，但还需要更明确的主角来支撑。\n\n## 优先修改项\n\n1. 问题：主体不明确。\n   为什么：画面里同时有树枝、水面、石头、左侧小路和右侧阴影，每个都不够强，观众视线会散。\n   下次怎么拍：先选一个主角，比如“一束光照在水面”“一块石头”“一段弯曲树枝”，其它元素都为它服务。\n   这张怎么修：尝试裁成竖幅或 4:5，只保留中间弯树枝、水面亮带和下方石头，删掉左右多余信息。\n\n2. 问题：明暗反差杂乱。\n   为什么：左侧水面高光、右侧深阴影和前景亮石头同时抢注意力。\n   下次怎么拍：避开正午直射光，等光线柔一点；或者只拍一块被光照到的局部。\n   这张怎么修：压低高光，提升右侧阴影一点点，但不要把阴影全拉亮；用局部暗角压住边缘。\n\n3. 问题：前景树枝遮挡多，但没有形成有效框景。\n   为什么：遮挡只有在能引导视线时才加分；现在树枝更多是在切碎画面。\n   下次怎么拍：移动机位，让枝条从边缘伸入，而不是横在中心；或用更长焦避开前景杂枝。\n   这张怎么修：降低树叶绿色饱和度和清晰度，让水面的视觉权重稍微上来。\n\n## 建议设置\n\n看不出实际相机参数，以下是估计：这种林荫水面可用 ISO 100-400、等效 35-70mm、f/5.6-f/8、快门 1/125 秒以上。如果想拍水面反光，先对亮水面减 0.3-0.7 档曝光补偿，避免反光过白。\n\n## 后期步骤\n\n1. 先裁切，确定唯一主体；建议从中心水面和弯树枝入手。\n2. 高光降低，尤其是左侧亮水面和前景亮石头。\n3. 阴影轻微提升，但保留右侧树林的深度。\n4. 降低全局绿色饱和度一点，避免满屏绿互相抢。\n5. 给选定主体加局部对比，其它区域降低清晰度。\n\n## 下一次练习任务\n\n在同类场景里只拍“一个光点”：找到一处光照水面、石头或树叶的地方，走近到它占画面至少三分之一，再按快门。\n"
