      "critique": "# 摄影点评：红窗建筑局部\n\n## 一句话总评\n\n这张把红窗和浅色墙面记录清楚了，但更像建筑局部资料照，左侧树干、右侧半扇窗和上下裁切让构图没有真正整理好。\n\n## 评分前检查\n\n- 主体：中间的红色窗户和墙面纹理。\n- 题材：建筑局部/窗户记录，偏普通 documentation。\n- 基础问题等级：基础问题。\n- 硬伤封顶检查：主体可读；没有严重失焦或曝光失败；但左侧树干、右侧半扇窗、墙面管线和上方截断同时干扰主体；画面以记录红窗信息为主，摄影故事较弱。\n- 高分资格：不具备。主体虽清楚，但边缘、对称、背景管线和裁切都没有控制到位。\n- 故意处理判断：正面平拍和居中可能是想做秩序感，但左右边缘不干净、上方元素截断，说明控制不足；平光不是有效的风格化处理。\n- 故事证据：记录信息。主要说明“这里有一扇红窗”，还没有形成明确情绪或视觉想法。\n\n## 五项评分\n\n- 技术：5.5\n- 构图：5\n- 光线：5\n- 叙事：4.5\n- 总体：5\n\n## 封顶规则\n\n普通建筑记录且边缘干扰明显，叙事封顶在 5；构图受左侧树干、右侧半窗和上方裁切影响，整体停在 5。\n\n## 做得好的地方\n\n- 红窗与浅色墙面有天然色彩对比，主体容易被识别。\n- 正面角度能表现窗格的几何图案。\n- 曝光基本可用，墙面和窗框细节没有完全丢失。\n\n## 优先修改项\n\n### 1. 清理画面边缘\n\n- 问题：左边树干贴边，右边露出半扇窗，上方红柱也被截断。\n- 为什么：建筑局部照片很依赖边缘干净；边缘一乱，画面就像随手截取。\n- 下次怎么拍：要么只拍中间完整红窗，让左右都留干净墙面；要么后退，把两扇窗完整纳入，做有秩序的重复。\n- 这张怎么修：裁掉左侧树干和右侧半窗，改成围绕中间红窗的更紧画面。\n\n### 2. 找到真正的对称\n\n- 问题：画面接近正面，但不是严格对称，也没有利用偏移产生节奏。\n- 为什么：这种窗格题材最怕“差一点对称”，会显得不稳。\n- 下次怎么拍：打开网格线，让窗户中心线和画面中心线重合；手机保持与墙面平行。\n- 这张怎么修：透视校正，拉直竖线和横线，再裁成更规整的矩形。\n\n### 3. 改善光线时间\n\n- 问题：光线偏平，墙面和窗格没有明显层次。\n- 为什么：平光适合记录，但不容易让建筑有质感。\n- 下次怎么拍：选早晚斜光，等窗框在墙上有轻微阴影；或者阴天拍更柔和、颜色更稳定的版本。\n- 这张怎么修：轻微增加对比和纹理，但不要把墙面污渍强化得太脏。\n\n## 建议设置\n\n看不出实际相机和参数，以下是估计：\n\n- 建筑局部：用 1x 或 2x，避免超广角造成边缘变形。\n- 对焦：点在红窗窗格上。\n- 曝光：对浅色墙面测光后略降 0.3 档，保住墙面细节。\n- 构图辅助：开启网格线，拍摄时让水平线和竖线贴合网格。\n- 拍摄距离：后退一点再裁切，比贴得太近更容易校正透视。\n\n## 后期步骤\n\n1. 做透视/水平校正，让墙砖线和窗框更直。\n2. 裁掉左树干、右半窗和上方多余截断。\n3. 降低墙面高光，轻微增加窗框红色饱和度。\n4. 对红窗加一点清晰度，墙面纹理少加，避免脏感。\n5. 如果整体偏灰，轻微增加对比。\n\n## 下一次练习任务\n\n拍 10 张“门窗正面构图”：每张只允许一种选择，完整居中对称，或完整偏左/偏右留空。拍完检查四条边：有没有半个物体、贴边树干、截断管线、歪斜墙线。\n\n归档路径：/Users/bytedance/Documents/摄影学习/data/archive/20260604-1782c264/\n"
